from __future__ import annotations

import pytest
from hypothesis import given, settings, strategies as st

from llm_router._internal.capabilities.schema import (
    build_repair_prompt,
    normalize_schema,
)

pytestmark = pytest.mark.verification_kind("unit")

_PREFIX = "Schema: "


@pytest.mark.verifies("TREQ_REPAIR_PROMPT_BOUNDS[revision==2]")
@settings(max_examples=30, deadline=None)
@given(
    length=st.integers(min_value=1_000, max_value=5_000),
    letter=st.sampled_from("abcxyz"),
)
def test_schema_name_is_capped_in_repair_prompt(length: int, letter: str) -> None:
    name = letter * length
    prompt = build_repair_prompt(
        spec=normalize_schema({"title": name, "type": "object"}),
        invalid_output="bad",
        error_message="oops",
    )
    lines = prompt.split("\n")
    schema_line = next(line for line in lines if line.startswith(_PREFIX))
    assert len(schema_line) - len(_PREFIX) <= 120
    assert len(prompt) <= 1_200
